package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.OrderService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;} @PostMapping public OrderResponse create(Authentication a,@Valid @RequestBody CreateOrderRequest r){return s.create(a,r);} @GetMapping public Page<OrderResponse> mine(Authentication a,Pageable p){return s.mine(a,p);} @GetMapping("/{id}") public OrderResponse get(Authentication a,@PathVariable UUID id){return s.get(id,a);} @PatchMapping("/{id}/cancel") public void cancel(Authentication a,@PathVariable UUID id){s.cancel(id,a);}}